    11	export interface DraftMetadata extends SavedDocumentState {
    12	  type?: CanvasType;
    13	  repositoryId?: string;
    14	  hidden?: boolean; newerRevision?: boolean; reloadKey?: string; representationId?: string;
    15	  revisionId: string; busy: boolean; viewport?: CanvasTransform; focusBox?: DiagramFocus;
    16	}
    17	export interface CanvasDraft extends DraftMetadata { session: CanvasSession }
    18	export type CanvasDraftSeed = DraftMetadata & Pick<ConstructorParameters<typeof CanvasSession>[0], 'document' | 'canvas' | 'history'>;
    19	type DraftInput = CanvasDraft | CanvasDraftSeed;
    20	type Drafts = Record<string, CanvasDraft>;
