    22	/** Registry owns session lifetimes. Page state contains metadata and stable handles only. */
    23	export class CanvasWorkspace {
    24	  private readonly storeState = createStore(() => ({ drafts: {} as Drafts }));
    25	  readonly controllers = new Map<string, MappingDocumentController>();
    26	  private readonly changesState = createStore(() => ({ version: 0 }));
    27	  private readonly dirtyScenesState = createStore(() => ({ ids: [] as string[] }));
    28	  readonly store = readable(this.storeState);
    29	  readonly changes = readable(this.changesState);
    30	  readonly dirtyScenes = readable(this.dirtyScenesState);
    31	  private subscriptions = new Map<string, (() => void)[]>();
    32	  constructor(private readonly history: CanvasHistoryService = new DefaultCanvasHistoryService()) {}
    33	  private persistenceListeners = new Set<(ids: string[]) => void>();
    34	  onPersist(listener: (ids: string[]) => void) { this.persistenceListeners.add(listener); return () => { this.persistenceListeners.delete(listener); }; }
    35	  private persist(ids: string[]) { this.persistenceListeners.forEach(listener => listener(ids)); }
    36	  private changed = () => this.changesState.setState(s => ({ version: s.version + 1 }));
    37	  private refreshDirty = () => {
    38	    const ids = Object.entries(this.store.getState().drafts).filter(([, d]) => d.session.status.getState().sceneDirty).map(([id]) => id);
    39	    const prior = this.dirtyScenes.getState().ids;
    40	    if (ids.length !== prior.length || ids.some((id, i) => id !== prior[i])) this.dirtyScenesState.setState({ ids });
    41	  };
    42	  copyDocument(input: { repositoryId?: string; documentId: string; name: string; expectedVersion?: number; display?: DisplayState; viewport?: CanvasTransform }) {
    43	    const source = this.store.getState().drafts[input.documentId];
    44	    if (!source || source.hidden) throw new Error('DOCUMENT_UNAVAILABLE');
    45	    if (source.busy) throw new Error('DOCUMENT_BUSY');
    46	    const name = input.name.trim();
    47	    if (!name || name.length > 120) throw new Error('Expected a canvas name between 1 and 120 characters');
    48	    const controller = source.session.controller, snapshot = controller.getSnapshot();
    49	    if (input.expectedVersion !== undefined && input.expectedVersion !== snapshot.version) throw new Error('VERSION_CONFLICT: read the source canvas again');
    50	    const canvas = structuredClone({ ...snapshot.canvas, display: input.display ?? snapshot.canvas.display, selection: { items: [] }, controls: initialCanvasState().controls });
    51	    // A copied conversation retains its messages, but has no running request.
    52	    for (const node of Object.values(canvas.display.nodes)) if (node.kind === 'conversation') node.thread.pending = false;
    53	    const documentId = `draft-${crypto.randomUUID()}`;
    54	    this.setDrafts(current => ({ ...current, [documentId]: {
    55	      type: source.type, name, repositoryId: input.repositoryId ?? source.repositoryId, savedName: '', revisionId: '', busy: false, document: snapshot.document, canvas,
    56	      history: controller.forkHistory(canvas), viewport: structuredClone(input.viewport ?? source.viewport),
    57	      savedScene: JSON.stringify(snapshot.document.scene), savedEdges: JSON.stringify(snapshot.document.edges)
    58	    } }));
    59	    return { documentId };
    60	  }
    61	  setDrafts = (value: Record<string, DraftInput> | ((current: Drafts) => Record<string, DraftInput>)) => {
    62	    const prior = this.store.getState().drafts;
    63	    const input = typeof value === 'function' ? value(prior) : value;
    64	    if (input === prior) return;
    65	    const next: Drafts = {};
    66	    let persist = false;
    67	    const changedIds = new Set<string>();
    68	    for (const [id, item] of Object.entries(input)) {
    69	      if (item === prior[id]) { next[id] = prior[id]; continue; }
    70	      if ('document' in item) {
    71	        const { document, canvas, history, ...metadata } = item;
    72	        next[id] = { ...metadata, type: canvasTypeOf({ ...metadata, canvas }), session: new CanvasSession({ ...metadata, document, canvas, history }, this.history) };
    73	      } else next[id] = item;
    74	      next[id].session.updateBaseline(next[id]);
    75	      const old = prior[id];
    76	      if (!old || next[id].session !== old.session || ['name', 'savedName', 'savedScene', 'savedEdges', 'revisionId', 'representationId', 'repositoryId', 'type', 'hidden'].some(key =>
    77	        old[key as keyof DraftMetadata] !== next[id][key as keyof DraftMetadata])) { persist = true; changedIds.add(id); }
    78	    }
    79	    for (const [id, old] of Object.entries(prior)) if (next[id]?.session !== old.session) {
    80	      this.subscriptions.get(id)?.forEach(unsubscribe => unsubscribe()); this.subscriptions.delete(id);
    81	      this.controllers.delete(id); old.session.dispose(); persist = true; changedIds.add(id);
    82	    }
    83	    for (const [id, draft] of Object.entries(next)) if (!this.subscriptions.has(id)) {
    84	      const session = draft.session;
    85	      this.controllers.set(id, session.controller);
    86	      this.subscriptions.set(id, [session.onCommit(() => { this.changed(); this.persist([id]); }), session.status.subscribe(this.refreshDirty), session.document.subscribe(() => {
    87	        // Document consumers (search/explorer) get a new entry; presentation/interaction never enter this path.
    88	        const current = this.store.getState().drafts;
    89	        if (current[id]?.session === session) this.storeState.setState({ drafts: { ...current, [id]: { ...current[id] } } });
    90	      })]);
    91	    }
    92	    this.storeState.setState({ drafts: next });
    93	    this.refreshDirty();
    94	    if (persist) { this.changed(); this.persist([...changedIds]); }
    95	  };
    96	  dispose() { this.subscriptions.forEach(list => list.forEach(off => off())); this.persistenceListeners.clear(); Object.values(this.store.getState().drafts).forEach(d => d.session.dispose()); }
    97	}
