     1	import type { CanvasHistoryService } from '../../../../domain/core/diagrams/canvasHistoryService';
     2	import { createStore, type StoreApi } from 'zustand/vanilla';
     3	
     4	import { MappingDocumentController, type ControllerSnapshot } from '../../../../domain/mapping/workspace/mappingDocumentController';
     5	import type { MappingGridDocument } from '../../../../domain/mapping/workspace/mappingGrid';
     6	import type { MappingCanvasState } from '../../../../domain/mapping/workspace/mappingWorkspace';
     7	import type { CanvasHistoryRecord } from '../../../../domain/core/diagrams/canvasHistory';
     8	import { stateKey } from '../../../../domain/core/diagrams/canvasHistory';
     9	import { CanvasCursorCopy } from '../canvas/cursorCopy';
    10	
    11	/** Consumers can select and subscribe; mutations stay behind session commands. */
    12	export function readable<T>(store: StoreApi<T>): Pick<StoreApi<T>, 'getState' | 'getInitialState' | 'subscribe'> {
    13	  return { getState: store.getState, getInitialState: store.getInitialState, subscribe: store.subscribe };
    14	}
    15	
    16	export interface SavedDocumentState { name: string; savedName: string; savedScene: string; savedEdges?: string }
    17	export interface DocumentStatus { isDirty: boolean; sceneDirty: boolean; canUndo: boolean; canRedo: boolean }
    18	
    19	/** Stores publish committed semantic checkpoints from the command facade. A mounted
    20	 * tldraw Editor owns live geometry and undo navigation; pointer/camera samples do
    21	 * not publish application state. Headless sessions use the same domain commands. */
    22	export class CanvasSession {
    23	  readonly cursorCopy = new CanvasCursorCopy();
    24	  readonly controller: MappingDocumentController;
    25	  readonly document;
    26	  private readonly documentState;
    27	  readonly presentation;
    28	  private readonly presentationState;
    29	  readonly selection;
    30	  private readonly selectionState;
    31	  readonly controls;
    32	  private readonly controlsState;
    33	  readonly geometry;
    34	  private readonly geometryState;
    35	  readonly status;
    36	  private readonly statusState;
    37	  private baseline: SavedDocumentState;
    38	  private savedSceneKey: string;
    39	  private savedEdgesKey: string;
    40	  private scene: MappingGridDocument['scene'];
    41	  private edges: MappingGridDocument['edges'];
    42	  private sceneKey: string;
    43	  private edgesKey: string;
    44	  private unsubscribe: () => void;
    45	  private commitListeners = new Set<() => void>();
    46	
    47	  constructor(input: SavedDocumentState & { document: MappingGridDocument; canvas: MappingCanvasState; history?: CanvasHistoryRecord }, history?: CanvasHistoryService) {
    48	    this.baseline = { name: input.name, savedName: input.savedName, savedScene: input.savedScene, savedEdges: input.savedEdges };
    49	    // Native anchors are renderer-local. Headless registry reads use estimated
    50	    // layout until a legacy renderer explicitly supplies measured endpoints.
    51	    this.controller = new MappingDocumentController(input.document, input.canvas, 0, undefined, undefined, input.history, history);
    52	    const snapshot = this.controller.getSnapshot();
    53	    this.scene = snapshot.document.scene; this.edges = snapshot.document.edges;
    54	    this.sceneKey = stateKey(this.scene); this.edgesKey = stateKey(this.edges);
    55	    this.savedSceneKey = stateKey(JSON.parse(input.savedScene)); this.savedEdgesKey = stateKey(JSON.parse(input.savedEdges ?? '[]'));
    56	    this.documentState = createStore(() => ({ document: snapshot.document }));
    57	    this.presentationState = createStore(() => ({ display: snapshot.canvas.display, diagramViews: snapshot.canvas.diagramViews }));
    58	    this.selectionState = createStore(() => snapshot.canvas.selection);
    59	    this.controlsState = createStore(() => snapshot.canvas.controls);
    60	    this.geometryState = createStore(() => this.geometryOf(snapshot));
    61	    this.statusState = createStore(() => this.statusOf(snapshot));
    62	    this.document = readable(this.documentState);
    63	    this.presentation = readable(this.presentationState);
    64	    this.selection = readable(this.selectionState);
    65	    this.controls = readable(this.controlsState);
    66	    this.geometry = readable(this.geometryState);
    67	    this.status = readable(this.statusState);
    68	    let previous = snapshot;
    69	    this.unsubscribe = this.controller.subscribe(() => {
    70	      const next = this.controller.getSnapshot();
    71	      if (next.document.scene !== this.scene) { this.scene = next.document.scene; this.sceneKey = stateKey(this.scene); }
    72	      if (next.document.edges !== this.edges) { this.edges = next.document.edges; this.edgesKey = stateKey(this.edges); }
    73	      // Publish all controller changes synchronously; React observes one completed transaction.
    74	      if (next.canvas.display !== previous.canvas.display || next.canvas.diagramViews !== previous.canvas.diagramViews)
    75	        this.presentationState.setState({ display: next.canvas.display, diagramViews: next.canvas.diagramViews });
    76	      if (next.canvas.selection !== previous.canvas.selection) this.selectionState.setState(next.canvas.selection, true);
    77	      if (next.canvas.controls !== previous.canvas.controls) this.controlsState.setState(next.canvas.controls, true);
    78	      if (next.endpointBounds !== previous.endpointBounds || next.cell !== previous.cell || next.version !== previous.version)
    79	        this.geometryState.setState(this.geometryOf(next));
    80	      this.publishStatus(next);
    81	      if (next.document !== previous.document) this.documentState.setState({ document: next.document });
    82	      const committed = next.canvasRevisionId !== previous.canvasRevisionId;
    83	      previous = next;
    84	      if (committed) this.commitListeners.forEach(listener => listener());
    85	    });
    86	  }
    87	  private geometryOf(s: ControllerSnapshot) { return { endpointBounds: s.endpointBounds, cell: s.cell, version: s.version }; }
    88	  private statusOf(s: ControllerSnapshot): DocumentStatus {
    89	    const sceneDirty = this.sceneKey !== this.savedSceneKey;
    90	    return { sceneDirty, isDirty: sceneDirty || this.edgesKey !== this.savedEdgesKey || this.baseline.name !== this.baseline.savedName,
    91	      canUndo: s.canUndo, canRedo: s.canRedo };
    92	  }
    93	  private publishStatus(s = this.controller.getSnapshot()) {
    94	    const next = this.statusOf(s), prior = this.status.getState();
    95	    if (Object.keys(next).some(key => next[key as keyof DocumentStatus] !== prior[key as keyof DocumentStatus])) this.statusState.setState(next);
    96	  }
    97	  /** A save acknowledgement names the captured baseline, not whatever is current now. */
    98	  updateBaseline(input: SavedDocumentState) {
    99	    if (input.savedScene !== this.baseline.savedScene) this.savedSceneKey = stateKey(JSON.parse(input.savedScene));
   100	    if (input.savedEdges !== this.baseline.savedEdges) this.savedEdgesKey = stateKey(JSON.parse(input.savedEdges ?? '[]'));
   101	    this.baseline = { name: input.name, savedName: input.savedName, savedScene: input.savedScene, savedEdges: input.savedEdges };
   102	    this.publishStatus();
   103	  }
   104	  onCommit(listener: () => void) { this.commitListeners.add(listener); return () => { this.commitListeners.delete(listener); }; }
   105	  dispose() { this.cursorCopy.clear(); this.unsubscribe(); this.commitListeners.clear(); }
   106	}
