    74	    parentLine: node.parentId ? nodes[node.parentId]?.line : undefined,
    75	    descendantLines: Object.values(nodes).filter(child => node.foldRanges.some(range => child.line >= range.startLine && child.line <= range.endLine)).map(child => child.line) }));
