    12	async function call<T>(name: string, input: unknown): Promise<T> {
    13	  const route = name === 'attach' ? '/attachments' : name === 'edit-diagram' ? '/diagram-edits'
    14	    : name === 'cancel-diagram-edit' ? `/diagram-edits/${encodeURIComponent((input as { runId: string }).runId)}/cancel`
    15	    : `/tools/${name}`;
    16	  const response = await apiFetch(`/api/mapping/agent${route}`, { method: 'POST',
    17	    headers: { 'content-type': 'application/json' }, body: JSON.stringify(input), signal: AbortSignal.timeout(65000) });
    18	  if (!response.ok) throw await errorFrom(response);
    19	  return response.json();
    20	}
    21	export function createDiagramEditClient(): DiagramEditClient {
    22	  const attachments = new Map<string, Promise<string>>();
    23	  return {
    24	    async capture(canvasId, documentId, nodeId) {
    25	      const key = JSON.stringify([canvasId, documentId]);
    26	      let attachment = attachments.get(key);
    27	      if (!attachment) {
    28	        attachment = call<{ value: { sessionId: string } }>('attach', { canvasId, documentId })
    29	          .then(result => result.value.sessionId).catch(error => { attachments.delete(key); throw error; });
    30	        attachments.set(key, attachment);
    31	      }
    32	      const sessionId = await attachment;
    33	      try {
    34	        if (nodeId === 'canvas') {
    35	          const read = await call<{ value: { version: number } }>('exec', { sessionId, requestId: crypto.randomUUID(), code: 'return nodes.list();' });
    36	          return { sessionId, expectedVersion: read.value.version, baseRevisionId: 'empty' };
    37	        }
    38	        const read = await call<{ version: number; node: { diagram?: { revisionId: string } } }>('diagram-search',
    39	          { operation: 'read', sessionId, nodeId });
    40	        if (!read.node.diagram) throw Error('The selected diagram is no longer available.');
    41	        return { sessionId, expectedVersion: read.version, baseRevisionId: read.node.diagram.revisionId };
    42	      } catch (error) { attachments.delete(key); throw error; }
    43	    },
    44	    start: (input, operation) => call(operation, input),
    45	    status: runId => call('edit-diagram-status', { runId }),
